#!/usr/bin/env python3
"""The fixtures of the splat viewer's placement (lot SV3 of the splat viewer), and what the tests compare with.

The page of the computers, phones and tablets places a splat by the rules of the Quest viewer (SplatPlacement.kt),
ported to JavaScript (mobile/assets/splat_viewer/placement.js). viewer_expected.json gives, for each case, the
positions the placement samples (as the file gives them back), and what the rules make of them: the bounds
(percentiles 5 and 95 of each axis), object or place, the floor rule, the orientation it opens in, and the first view
on a screen of 16:9. Three readers check it, so that the expectations come from the rules and not from one port:

  * test/splat_viewer_js/placement.test.mjs (Node): placement.js on the positions;
  * SplatPlacementViewerTest.kt (JUnit, through ktc and in the release workflow): the Quest's SplatPlacement on them;
  * page_check.py (headless Chromium): the page on the files, Spark decoding them (float16 centres: a tolerance).

New files, in mobile/test/fixtures/splat_viewer (the axes, the room and the writers of make_splat_fixtures.py):

  axes_brush_order.ply   the axes of make_splat_fixtures.py with the properties in alphabetical order, as Brush writes
  room_floor.spz         a room of 3 000 gaussians, version 2, its floor at the bottom of y: a place, Y up by the
                         floor rule
  room_colmap.spz        the same room with y down (the axes of COLMAP): a place, Y down by default
  small_object.ply       a box of 0.3 m: an object, Y down by default

  make_viewer_fixtures.py           writes the files and viewer_expected.json
  make_viewer_fixtures.py --check   exit 1 when a file differs from what this script writes
"""
from __future__ import annotations

import argparse
import importlib.util
import json
import math
import pathlib
import struct
import sys
import types

HERE = pathlib.Path(__file__).resolve().parent
ROOT = HERE.parents[2]
FIXTURES = ROOT / 'mobile/test/fixtures/splat'
OUT = ROOT / 'mobile/test/fixtures/splat_viewer'

# make_splat_fixtures.py imports zstandard for its version 4 files, which are not written here
if importlib.util.find_spec('zstandard') is None:
    sys.modules['zstandard'] = types.ModuleType('zstandard')
_spec = importlib.util.spec_from_file_location('make_splat_fixtures', ROOT / '.github/desktop/ai/make_splat_fixtures.py')
msf = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(msf)

# The rules of SplatPlacement.kt and of placement.js
OBJECT_LIMIT = 2.5
OBJECT_GAP = 0.6
SCENE_DROP = 0.3
FLOOR_BAND = 0.1
FLOOR_RATIO = 3.0
FLOOR_SHARE = 0.15
SAMPLE_LIMIT = 65536
EYE_HEIGHT = 1.6
NARROW_FOV = 60.0
FIT_MARGIN = 1.05


def f32(value: float) -> float:
    return struct.unpack('<f', struct.pack('<f', value))[0]


def write_ply_brush_order(gaussians) -> bytes:
    """The axes as a PLY whose properties come in alphabetical order (f_dc, opacity, rot, scale, x y z), as Brush"""
    names = ['f_dc_0', 'f_dc_1', 'f_dc_2', 'opacity', 'rot_0', 'rot_1', 'rot_2', 'rot_3', 'scale_0', 'scale_1',
             'scale_2', 'x', 'y', 'z']
    header = ['ply', 'format binary_little_endian 1.0', 'comment Generated by make_viewer_fixtures.py',
              f'element vertex {len(gaussians)}', *[f'property float {n}' for n in names], 'end_header']
    out = bytearray(('\n'.join(header) + '\n').encode('ascii'))
    for g in gaussians:
        values = {
            'f_dc_0': (g.color[0] - 0.5) / msf.SH_C0, 'f_dc_1': (g.color[1] - 0.5) / msf.SH_C0,
            'f_dc_2': (g.color[2] - 0.5) / msf.SH_C0, 'opacity': msf.logit(g.alpha),
            'rot_0': 1.0, 'rot_1': 0.0, 'rot_2': 0.0, 'rot_3': 0.0,
            'scale_0': math.log(g.scale[0]), 'scale_1': math.log(g.scale[1]), 'scale_2': math.log(g.scale[2]),
            'x': g.position[0], 'y': g.position[1], 'z': g.position[2],
        }
        out += struct.pack(f'<{len(names)}f', *[values[n] for n in names])
    return bytes(out)


def flipped_y(gaussians) -> list:
    """The same gaussians with y down (and z mirrored to stay right handed): the axes of COLMAP"""
    out = []
    for g in gaussians:
        x, y, z = g.position
        out.append(msf.Gaussian(x, -y, -z, *g.color, g.alpha, *g.scale))
    return out


def small_object() -> list:
    """A box of 0.3 m: its 12 edges in gaussians 1 cm apart, red, green and blue by direction"""
    out = []
    size = 0.3
    steps = 30
    for axis, color in ((0, (0.9, 0.2, 0.2)), (1, (0.2, 0.9, 0.2)), (2, (0.2, 0.3, 0.95))):
        others = [a for a in range(3) if a != axis]
        for corner in range(4):
            for k in range(steps + 1):
                p = [0.0, 0.0, 0.0]
                p[axis] = k * size / steps
                p[others[0]] = size if corner & 1 else 0.0
                p[others[1]] = size if corner & 2 else 0.0
                out.append(msf.Gaussian(*p, *color, 0.95, 0.006))
    return out


def files() -> dict:
    room = msf.room(3000, seed=5)
    return {
        'axes_brush_order.ply': (write_ply_brush_order(msf.axes()), msf.axes(), 'ply'),
        'room_floor.spz': (msf.write_spz(room, 2), room, 'spz2'),
        'room_colmap.spz': (msf.write_spz(flipped_y(room), 2), flipped_y(room), 'spz2'),
        'small_object.ply': (msf.write_ply(small_object(), comments=['Generated by make_viewer_fixtures.py']),
                             small_object(), 'ply'),
    }


def positions_as_read(gaussians, kind: str) -> list:
    """The positions as the file gives them back: float32 for a PLY, the fixed point or float16 of an SPZ"""
    if kind == 'ply':
        return [tuple(f32(v) for v in g.position) for g in gaussians]
    return msf.quantized_positions(gaussians, 1 if kind == 'spz1' else 2)


def percentile(values, p: int) -> float:
    ordered = sorted(values)
    rank = max(1, (p * len(ordered) + 99) // 100)
    return ordered[rank - 1]


def rotate_x(angle: float, v) -> list:
    c, s = math.cos(angle), math.sin(angle)
    return [v[0], v[1] * c - v[2] * s, v[1] * s + v[2] * c]


def case(name: str, gaussians, kind: str) -> dict:
    """What the placement makes of the file [name]"""
    positions = positions_as_read(gaussians, kind)
    count = len(positions)
    stride = max(1, (count + SAMPLE_LIMIT - 1) // SAMPLE_LIMIT)
    sample = positions[::stride]
    low = [percentile([p[a] for p in sample], 5) for a in range(3)]
    high = [percentile([p[a] for p in sample], 95) for a in range(3)]
    size = max(high[a] - low[a] for a in range(3))
    is_object = size < OBJECT_LIMIT
    floor = None
    if not is_object:
        band = (high[1] - low[1]) * FLOOR_BAND
        if band > 0:
            ys = [p[1] for p in sample]
            bottom = sum(1 for y in ys if y <= low[1] + band)
            top = sum(1 for y in ys if y >= high[1] - band)
            if bottom >= FLOOR_SHARE * len(ys) and bottom >= FLOOR_RATIO * top:
                floor = 'yUp'
    upright = floor or 'yDown'
    pitch = {'yUp': 0.0, 'zUp': -math.pi / 2, 'yDown': math.pi}[upright]
    half = math.radians(NARROW_FOV / 2)
    radius = math.sqrt(sum((high[a] - low[a]) ** 2 for a in range(3))) / 2
    distance = max(OBJECT_GAP + size / 2, radius / math.sin(half) * FIT_MARGIN) if is_object else 0.0
    target = [0.0, EYE_HEIGHT, -distance] if is_object else [0.0, EYE_HEIGHT - SCENE_DROP, 0.0]
    center = [(low[a] + high[a]) / 2 for a in range(3)]
    rotated = rotate_x(pitch, center)
    position = [target[a] - rotated[a] for a in range(3)]
    # The Quest's target, in its frame (z ahead), as SplatPlacement.target gives it
    quest_target = [0.0, 0.0, OBJECT_GAP + size / 2] if is_object else [0.0, -SCENE_DROP, 0.0]
    return {
        'type': 'ply' if kind == 'ply' else 'spz',
        'count': count,
        'stride': stride,
        'positions': [v for p in sample for v in p],
        'bounds': {'low': low, 'high': high},
        'size': size,
        'object': is_object,
        'floorUpright': floor,
        'upright': upright,
        'questTarget': quest_target,
        'view': {'pitch': pitch, 'position': position, 'target': target, 'distance': distance,
                 'speed': min(4.0, max(0.5, size / 8))},
    }


def expected(made: dict) -> dict:
    axes = msf.axes()
    out = {'about': 'What the placement tests compare with, written by .github/desktop/splat_viewer/'
                    'make_viewer_fixtures.py'}
    out['axes_v1.spz'] = case('axes_v1.spz', axes, 'spz1')
    out['axes_v2.spz'] = case('axes_v2.spz', axes, 'spz2')
    out['axes_v3.spz'] = case('axes_v3.spz', axes, 'spz2')
    out['axes.ply'] = case('axes.ply', axes, 'ply')
    for name, (_, gaussians, kind) in made.items():
        out[name] = case(name, gaussians, kind)
    return out


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.split('\n\n')[0])
    parser.add_argument('--check', action='store_true')
    arguments = parser.parse_args()
    made = files()
    cases = expected(made)
    # One case a line: the positions make it long otherwise
    text = '{\n' + ',\n'.join(f'{json.dumps(k)}: {json.dumps(v, separators=(",", ":"))}' for k, v in cases.items()) + '\n}\n'
    if arguments.check:
        bad = [name for name, (data, _, _) in made.items()
               if not (OUT / name).is_file() or (OUT / name).read_bytes() != data]
        if not (OUT / 'viewer_expected.json').is_file() or (OUT / 'viewer_expected.json').read_text() != text:
            bad.append('viewer_expected.json')
        for name in bad:
            print(f'differs: {name}')
        return 1 if bad else 0
    OUT.mkdir(parents=True, exist_ok=True)
    for name, (data, _, _) in made.items():
        (OUT / name).write_bytes(data)
    (OUT / 'viewer_expected.json').write_text(text)
    print(f'{len(made)} files and viewer_expected.json in {OUT.relative_to(ROOT)}')
    return 0


if __name__ == '__main__':
    sys.exit(main())
